     1→"use client";
     2→
     3→import { useQuery, useQueryClient } from "@tanstack/react-query";
     4→import {
     5→  Bell,
     6→  Check,
     7→  ChevronRight,
     8→  Circle,
     9→  History,
    10→  Moon,
    11→  MessageSquare,
    12→  Pill,
    13→  Plus,
    14→  PlusCircle,
    15→  Sparkles,
    16→  TrendingUp,
    17→  Users,
    18→} from "lucide-react";
    19→import Link from "next/link";
    20→import { useState } from "react";
    21→
    22→import { Button } from "@/components/ui/button";
    23→import { Skeleton } from "@/components/ui/skeleton";
    24→import {
    25→  GlassCard,
    26→  GlassCardBadge,
    27→  GlassCardContent,
    28→  GlassCardHeader,
    29→  GlassCardTitle,
    30→} from "@/components/nowts/glass-card";
    31→import { MoodSlider } from "@/components/nowts/mood-slider";
    32→import { StreakCard } from "@/components/nowts/streak-card";
    33→import { MoodChart } from "@/components/nowts/mood-chart";
    34→import { saveMoodEntry } from "@/features/mood/mood.action";
    35→import {
    36→  getDashboardSummary,
    37→  getMoodChartData,
    38→  getPatternInsights,
    39→  getStreakData,
    40→} from "@/features/insights/insights.action";
    41→import {
    42→  getTodayIntakes,
    43→  logMedIntake,
    44→  skipMedIntake,
    45→} from "@/features/medication/medication.action";
    46→import { getMyCaregivers } from "@/features/caregiver/caregiver.action";
    47→import { toast } from "sonner";
    48→import { cn } from "@/lib/utils";
    49→import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
    50→
    51→type DashboardContentProps = {
    52→  userName: string;
    53→};
    54→
    55→export function DashboardContent({ userName }: DashboardContentProps) {
    56→  const queryClient = useQueryClient();
    57→  const [currentMood, setCurrentMood] = useState(7);
    58→  const [isSaving, setIsSaving] = useState(false);
    59→
    60→  // Fetch dashboard data
    61→  const { data: summary } = useQuery({
    62→    queryKey: ["dashboard-summary"],
    63→    queryFn: async () => {
    64→      const result = await getDashboardSummary();
    65→      if (result.serverError) throw new Error(result.serverError);
    66→      return result.data;
    67→    },
    68→  });
    69→
    70→  const { data: chartData, isLoading: chartLoading } = useQuery({
    71→    queryKey: ["mood-chart", 7],
    72→    queryFn: async () => {
    73→      const result = await getMoodChartData({ days: 7 });
    74→      if (result.serverError) throw new Error(result.serverError);
    75→      return result.data;
    76→    },
    77→  });
    78→
    79→  const { data: insights } = useQuery({
    80→    queryKey: ["pattern-insights"],
    81→    queryFn: async () => {
    82→      const result = await getPatternInsights();
    83→      if (result.serverError) throw new Error(result.serverError);
    84→      return result.data;
    85→    },
    86→  });
    87→
    88→  // Fetch streak data
    89→  const { data: streakData, isLoading: streakLoading } = useQuery({
    90→    queryKey: ["streak-data"],
    91→    queryFn: async () => {
    92→      const result = await getStreakData();
    93→      if (result.serverError) throw new Error(result.serverError);
    94→      return result.data;
    95→    },
    96→  });
    97→
    98→  // Fetch today's medications
    99→  const {
   100→    data: medications,
   101→    isLoading: medicationsLoading,
   102→    refetch: refetchMedications,
   103→  } = useQuery({
   104→    queryKey: ["today-intakes"],
   105→    queryFn: async () => {
   106→      const result = await getTodayIntakes({});
   107→      if (result.serverError) throw new Error(result.serverError);
   108→      return result.data ?? [];
   109→    },
   110→  });
   111→
   112→  const { data: caregivers, isLoading: caregiversLoading } = useQuery({
   113→    queryKey: ["dashboard-caregivers"],
   114→    queryFn: async () => {
   115→      const result = await getMyCaregivers();
   116→      if (result.serverError) throw new Error(result.serverError);
   117→      return result.data ?? [];
   118→    },
   119→  });
   120→
   121→  // Handle medication intake toggle
   122→  const handleMedIntake = async (medicationId: string, isTaken: boolean) => {
   123→    try {
   124→      if (isTaken) {
   125→        // Already taken, skip for now (could add undo functionality)
   126→        return;
   127→      }
   128→      const result = await logMedIntake({ medicationId });
   129→      if (result.serverError) {
   130→        toast.error(result.serverError);
   131→        return;
   132→      }
   133→      toast.success("Prise enregistrée !");
   134→      void refetchMedications();
   135→    } catch {
   136→      toast.error("Une erreur est survenue");
   137→    }
   138→  };
   139→
   140→  // Handle skip medication
   141→  const handleSkipMed = async (medicationId: string) => {
   142→    try {
   143→      const result = await skipMedIntake({ medicationId });
   144→      if (result.serverError) {
   145→        toast.error(result.serverError);
   146→        return;
   147→      }
   148→      toast.success("Prise sautée");
   149→      void refetchMedications();
   150→    } catch {
   151→      toast.error("Une erreur est survenue");
   152→    }
   153→  };
   154→
   155→  // Get today's date formatted
   156→  const today = new Date().toLocaleDateString("fr-FR", {
   157→    weekday: "long",
   158→    day: "numeric",
   159→    month: "long",
   160→    year: "numeric",
   161→  });
   162→
   163→  // Handle mood save
   164→  const handleSaveMood = async () => {
   165→    setIsSaving(true);
   166→    try {
   167→      const result = await saveMoodEntry({ value: currentMood });
   168→      if (result.serverError) {
   169→        toast.error(result.serverError);
   170→        return;
   171→      }
   172→      toast.success("Humeur enregistrée !");
   173→      await Promise.all([
   174→        queryClient.invalidateQueries({ queryKey: ["dashboard-summary"] }),
   175→        queryClient.invalidateQueries({ queryKey: ["mood-chart"] }),
   176→        queryClient.invalidateQueries({ queryKey: ["streak-data"] }),
   177→        queryClient.invalidateQueries({ queryKey: ["pattern-insights"] }),
   178→      ]);
   179→    } catch {
   180→      toast.error("Une erreur est survenue");
   181→    } finally {
   182→      setIsSaving(false);
   183→    }
   184→  };
   185→
   186→  // Calculate taken count from real medications data
   187→  const takenCount =
   188→    medications?.filter((m) => m.intakes.length > 0 && !m.intakes[0].skipped)
   189→      .length ?? 0;
   190→
   191→  return (
   192→    <div className="mx-auto max-w-7xl px-4 pb-8 lg:px-6">
   193→      {/* Background Decorations */}
   194→      <div className="blob blob-primary -top-[200px] -left-[100px]" />
   195→      <div className="blob blob-lavender -right-[100px] -bottom-[200px]" />
   196→
   197→      {/* Header */}
   198→      <header className="mb-10 flex items-center justify-between">
   199→        <div>
   200→          <h1 className="text-2xl font-bold text-gray-900 lg:text-3xl">
   201→            Bonjour {userName.split(" ")[0]} !
   202→          </h1>
   203→          <p className="text-gray-500">
   204→            Aujourd&apos;hui, nous sommes le {today}
   205→          </p>
   206→        </div>
   207→        <div className="flex items-center gap-4">
   208→          <button className="glass-card relative flex size-12 items-center justify-center rounded-2xl text-gray-600 transition-all hover:text-[var(--primary)]">
   209→            <Bell className="size-6" />
   210→            <span className="absolute top-3 right-3 size-2 rounded-full bg-[var(--destructive)] ring-2 ring-white" />
   211→          </button>
   212→        </div>
   213→      </header>
   214→
   215→      <div className="grid gap-8 lg:grid-cols-12">
   216→        {/* Left Column: Core Tracking */}
   217→        <div className="space-y-8 lg:col-span-8">
   218→          {/* Quick Mood Section */}
   219→          <GlassCard
   220→            padding="lg"
   221→            variant="elevated"
   222→            className="group relative overflow-hidden"
   223→          >
   224→            <div className="relative z-10">
   225→              <GlassCardHeader>
   226→                <div>
   227→                  <h2 className="mb-1 text-xl font-bold">
   228→                    Comment vous sentez-vous ?
   229→                  </h2>
   230→                  <p className="text-sm text-gray-500">
   231→                    Prenez un instant pour vous écouter.
   232→                  </p>
   233→                </div>
   234→                <GlassCardBadge>Saisie rapide</GlassCardBadge>
   235→              </GlassCardHeader>
   236→
   237→              <div className="my-8">
   238→                <MoodSlider value={currentMood} onChange={setCurrentMood} />
   239→              </div>
   240→
   241→              <div className="flex gap-3">
   242→                <Button
   243→                  onClick={handleSaveMood}
   244→                  disabled={isSaving}
   245→                  className="shadow-soft flex-grow rounded-2xl bg-[var(--primary)] py-6 text-lg font-bold text-white transition-all hover:bg-[var(--primary-dark)] active:scale-[0.98]"
   246→                >
   247→                  {isSaving ? "Enregistrement..." : "Enregistrer l'humeur"}
   248→                </Button>
   249→                <Link
   250→                  href="/mood"
   251→                  className="glass-card flex items-center justify-center rounded-2xl px-6 font-bold text-[var(--primary)] transition-all hover:bg-white"
   252→                >
   253→                  <Plus className="size-6" />
   254→                </Link>
   255→              </div>
   256→            </div>
   257→          </GlassCard>
   258→
   259→          {/* Grid: Meds & Sleep */}
   260→          <div className="grid gap-8 md:grid-cols-2">
   261→            {/* Medication Card */}
   262→            <GlassCard padding="md" variant="elevated">
   263→              <GlassCardHeader>
   264→                <GlassCardTitle
   265→                  icon={<Pill className="size-5 text-[var(--primary)]" />}
   266→                >
   267→                  Traitements
   268→                </GlassCardTitle>
   269→                <GlassCardBadge>
   270→                  {takenCount}/{medications?.length ?? 0}
   271→                </GlassCardBadge>
   272→              </GlassCardHeader>
   273→
   274→              <GlassCardContent className="space-y-3">
   275→                {medicationsLoading ? (
   276→                  <div className="space-y-3">
   277→                    <Skeleton className="h-16 w-full rounded-2xl" />
   278→                    <Skeleton className="h-16 w-full rounded-2xl" />
   279→                    <Skeleton className="h-16 w-full rounded-2xl" />
   280→                  </div>
   281→                ) : medications && medications.length > 0 ? (
