   328→function MedicationRow({
   329→  medication,
   330→  onTake,
   331→  isPending = false,
   332→  isArchived = false,
   333→}: {
   334→  medication: MedicationWithIntakes;
   335→  onTake?: () => void;
   336→  isPending?: boolean;
   337→  isArchived?: boolean;
   338→}) {
   339→  const { t } = useI18n();
   340→  const hasTakenToday = medication.intakes.some((intake) => !intake.skipped);
   341→  const frequencyLabel =
   342→    FREQUENCY_LABELS[medication.frequency] ?? FREQUENCY_LABELS.daily;
   343→
   344→  const handleToggle = (e: React.MouseEvent) => {
   345→    e.preventDefault();
   346→    e.stopPropagation();
   347→    if (!hasTakenToday && onTake && !isArchived) {
   348→      onTake();
   349→    }
   350→  };
   351→
   352→  return (
   353→    <Link href={`/medications/${medication.id}`}>
   354→      <div
   355→        className={cn(
   356→          "group flex cursor-pointer items-center gap-4 rounded-2xl border p-4 transition-all",
   357→          hasTakenToday
   358→            ? "border-[var(--sage)]/20 bg-[var(--sage)]/5"
   359→            : "border-gray-100 bg-white hover:border-[var(--primary)]/30 hover:shadow-sm",
   360→          isArchived && "opacity-60",
   361→        )}
   362→      >
   363→        {/* Toggle Button */}
   364→        <button
   365→          onClick={handleToggle}
   366→          disabled={hasTakenToday || isPending || isArchived}
   367→          className={cn(
   368→            "flex size-12 shrink-0 items-center justify-center rounded-xl transition-all",
   369→            hasTakenToday
   370→              ? "bg-[var(--sage)] text-white"
   371→              : "bg-gray-50 text-gray-300 hover:bg-[var(--primary)]/10 hover:text-[var(--primary)]",
   372→            (isPending || isArchived) && "cursor-not-allowed opacity-50",
   373→          )}
   374→        >
   375→          {hasTakenToday ? (
   376→            <Check className="size-6" />
   377→          ) : (
   378→            <Circle className="size-6" />
   379→          )}
   380→        </button>
   381→
   382→        {/* Content */}
   383→        <div className="min-w-0 flex-1">
   384→          <div className="flex items-center gap-2">
   385→            <span
   386→              className={cn(
   387→                "font-bold",
   388→                hasTakenToday ? "text-[var(--sage-dark)]" : "text-gray-800",
   389→              )}
   390→            >
   391→              {medication.name}
   392→            </span>
   393→            {medication.isPRN && (
   394→              <Badge
   395→                variant="outline"
   396→                className="rounded-lg border-[var(--lavender)]/30 bg-[var(--lavender)]/10 text-[10px] font-bold text-[var(--lavender-dark)]"
   397→              >
   398→                {t("medication.prn.badge")}
   399→              </Badge>
   400→            )}
   401→          </div>
   402→          <p className="text-sm text-gray-400">
   403→            {medication.dosage} • {frequencyLabel}
   404→          </p>
   405→        </div>
   406→
   407→        {/* Status & Arrow */}
   408→        <div className="flex items-center gap-3">
   409→          {!isArchived && !medication.isPRN && (
   410→            <span
   411→              className={cn(
   412→                "flex items-center gap-1 text-xs font-medium",
   413→                hasTakenToday ? "text-[var(--sage)]" : "text-gray-400",
   414→              )}
   415→            >
   416→              {hasTakenToday ? (
   417→                <>
   418→                  <Check className="size-3" />
   419→                  Pris
   420→                </>
   421→              ) : (
   422→                <>
   423→                  <Clock className="size-3" />
   424→                  En attente
   425→                </>
   426→              )}
   427→            </span>
   428→          )}
   429→          <ChevronRight className="size-5 text-gray-300 transition-transform group-hover:translate-x-1" />
   430→        </div>
   431→      </div>
   432→    </Link>
   433→  );
   434→}
