    28→function ObservePageContent() {
    29→  const searchParams = useSearchParams();
    30→  const router = useRouter();
    31→  const { data: session, isPending } = useSession();
    32→  const { data: patients, isLoading: patientsLoading } = useQuery({
    33→    queryKey: ["my-patients"],
    34→    queryFn: async () => {
    35→      const result = await getMyPatients();
    36→      if (result.serverError) throw new Error(result.serverError);
    37→      return result.data ?? [];
    38→    },
    39→  });
    40→  const initialTab = searchParams.get("tab") === "event" ? "event" : "checkin";
    41→  const [activeTab, setActiveTab] = useState(initialTab);
    42→  const [selectedPatientId, setSelectedPatientId] = useState<string | null>(
    43→    null,
    44→  );
    45→
    46→  useEffect(() => {
    47→    if (patients && patients.length > 0 && !selectedPatientId) {
    48→      setSelectedPatientId(patients[0].patientId);
    49→    }
    50→  }, [patients, selectedPatientId]);
    51→
    52→  const handleSuccess = () => {
    53→    router.push("/caregiver");
    54→  };
    55→
    56→  const resolvedPatient =
    57→    selectedPatientId && patients
    58→      ? patients.find((p) => p.patientId === selectedPatientId)
    59→      : patients?.[0];
    60→
    61→  const subject = resolvedPatient
    62→    ? { id: resolvedPatient.patientId, name: resolvedPatient.patientName }
    63→    : session?.user
    64→      ? { id: session.user.id, name: session.user.name || "Moi" }
    65→      : null;
    66→
    67→  if (isPending) {
    68→    return (
    69→      <div className="container mx-auto max-w-2xl px-4 py-8">
    70→        <Skeleton className="mb-6 h-10 w-24" />
    71→        <Skeleton className="mb-4 h-8 w-48" />
    72→        <Skeleton className="h-96 w-full" />
    73→      </div>
    74→    );
    75→  }
    76→
    77→  if (!subject) {
    78→    return (
    79→      <div className="container mx-auto max-w-2xl px-4 py-8">
    80→        <p className="text-muted-foreground">Utilisateur non connecté</p>
    81→      </div>
    82→    );
    83→  }
    84→
    85→  return (
    86→    <div className="container mx-auto max-w-2xl px-4 py-8">
    87→      <div className="mb-6">
    88→        <Button asChild variant="ghost" size="sm">
    89→          <Link href="/caregiver">
    90→            <ArrowLeft className="mr-2 size-4" />
    91→            Retour
    92→          </Link>
    93→        </Button>
    94→      </div>
    95→
    96→      <PageHeader
    97→        title="Nouvelle observation"
    98→        description={`Enregistre une observation pour ${subject.name}`}
    99→      />
   100→
   101→      <Card>
   102→        <CardHeader>
   103→          {!patientsLoading && patients && patients.length > 0 && (
   104→            <div className="mb-6 space-y-2">
   105→              <Label>Patient</Label>
   106→              <Select
   107→                value={subject?.id ?? ""}
   108→                onValueChange={(value) => setSelectedPatientId(value)}
   109→              >
   110→                <SelectTrigger>
   111→                  <SelectValue placeholder="Sélectionner un patient" />
   112→                </SelectTrigger>
   113→                <SelectContent>
   114→                  {patients.map((patient) => (
   115→                    <SelectItem key={patient.patientId} value={patient.patientId}>
   116→                      {patient.patientName}
   117→                    </SelectItem>
   118→                  ))}
   119→                </SelectContent>
   120→              </Select>
   121→            </div>
   122→          )}
   123→          <Tabs value={activeTab} onValueChange={setActiveTab}>
   124→            <TabsList className="grid w-full grid-cols-2">
   125→              <TabsTrigger value="checkin" className="flex items-center gap-2">
   126→                <Eye className="size-4" />
   127→                Check-in
   128→              </TabsTrigger>
   129→              <TabsTrigger value="event" className="flex items-center gap-2">
   130→                <AlertTriangle className="size-4" />
   131→                Événement
   132→              </TabsTrigger>
   133→            </TabsList>
   134→          </Tabs>
   135→        </CardHeader>
   136→        <CardContent>
   137→          <Tabs value={activeTab} onValueChange={setActiveTab}>
   138→            <TabsContent value="checkin" className="mt-0">
   139→              <CaregiverCheckinForm
   140→                subjectId={subject.id}
   141→                subjectName={subject.name}
   142→                onSuccess={handleSuccess}
   143→              />
   144→            </TabsContent>
   145→            <TabsContent value="event" className="mt-0">
   146→              <CaregiverEventForm
   147→                subjectId={subject.id}
   148→                subjectName={subject.name}
   149→                onSuccess={handleSuccess}
   150→              />
   151→            </TabsContent>
   152→          </Tabs>
   153→        </CardContent>
   154→      </Card>
   155→    </div>
   156→  );
   157→}
   158→
   159→export default function ObservePage() {
   160→  return (
   161→    <Suspense
   162→      fallback={
   163→        <div className="container mx-auto max-w-2xl px-4 py-8">
   164→          Chargement...
   165→        </div>
   166→      }
   167→    >
   168→      <ObservePageContent />
   169→    </Suspense>
   170→  );
   171→}
